// build URLs — mode: runOnceForEachItem
const raw = $json["Website"] || "";
const domain = raw.replace(/^https?:\/\//, "").replace(/\/$/, "").trim();
const companyName = $json["Company Name"] || domain;

// ✅ Skip if domain is missing
if (!domain) {
  return [{
    json: {
      "Company Name":    companyName,
      "Website": "",
      fetch_url:         null,
      url_type:          null,
      try_index:         null,
      skip_reason:       "Missing domain"
    }
  }];
}

const urls = [
  { url: `https://${domain}/terms`,            type: "tos",     tryIndex: 0 },
  { url: `https://${domain}/terms-of-service`, type: "tos",     tryIndex: 1 },
  { url: `https://${domain}/legal/terms`,      type: "tos",     tryIndex: 2 },
  { url: `https://${domain}/privacy`,          type: "privacy", tryIndex: 3 },
  { url: `https://${domain}/privacy-policy`,   type: "privacy", tryIndex: 4 },
  { url: `https://${domain}/legal/privacy`,    type: "privacy", tryIndex: 5 },
];

return urls.map(u => ({
  json: {
    "Company Name":    companyName,
    "Company Website": $json["Website"],
    fetch_url:         u.url,
    url_type:          u.type,
    try_index:         u.tryIndex,
  }
}));

const parsed = JSON.parse($json.data);

const content = (parsed.markdown || "").toLowerCase();

let valid = true;

if (
  content.includes("404") ||
  content.includes("page not found")
) {
  valid = false;
}

if (content.length < 300) {
  valid = false;
}

return {
  ...$json,
  markdown: parsed.markdown,
  valid
};

const raw = $json.content?.[0]?.text || "";

// Extract summary
const summaryMatch = raw.match(/"summary"\s*:\s*"([\s\S]*?)",\s*"issues"/);

// Extract issues
const issuesMatch = raw.match(/"issues"\s*:\s*"([\s\S]*?)",\s*"severity"/);

// Extract severity
const severityMatch = raw.match(/"severity"\s*:\s*"([\s\S]*?)"/);

return {
  summary: summaryMatch ? summaryMatch[1] : "",
  issues: issuesMatch ? issuesMatch[1] : "",
  severity: severityMatch ? severityMatch[1] : ""
};

for (const item of $input.all()) {

  if (item.json.tos_content) {
    item.json.tos_content =
      item.json.tos_content.slice(0, 5000);
  }

  if (item.json.privacy_content) {
    item.json.privacy_content =
      item.json.privacy_content.slice(0, 5000);
  }
}

return $input.all();

