const items = $input.all();

let tosContent = "";
let privacyContent = "";

for (const item of items) {

  const row = item.json;

  // ONLY process valid=true items
  if (row.valid !== true) {
    continue;
  }

  let markdown = row.markdown || "";

  // if markdown stored inside data JSON string
  if (!markdown && row.data) {
    try {
      const parsed = JSON.parse(row.data);
      markdown = parsed.markdown || "";
    } catch (e) {
      markdown = row.data || "";
    }
  }

  const type = row.url_type || "";

  // Merge ToS content
  if (type === "tos") {
    tosContent += "\n\n" + markdown;
  }

  // Merge Privacy content
  if (type === "privacy") {
    privacyContent += "\n\n" + markdown;
  }
}

return [
  {
    json: {
      "Company Name": items[0]?.json["Company Name"],
      "Company Website": items[0]?.json["Company Website"],

      tos_content: tosContent.trim(),

      privacy_content: privacyContent.trim()
    }
  }
];
